#!/bin/sh
# usage: fold_chain.sh <gpu> <A|B>   train on one Miami group, decode the other group (out-of-fold), T and dev
G=$2; if [ $G = A ]; then OTHER=B; else OTHER=A; fi
export CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=$1 HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 TOKENIZERS_PARALLELISM=false KF_VAL=miami_Tsel600 KF_TAG=_frag KF_MANIFEST=manifest_frag.jsonl KF_REFS=refs_frag.csv KF_EXTRA_FRAC=0 KF_AUG=0
cd /kaggle/working/omni_rt/work
/kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_train.py /home/jovyan/work/Enes/lost_in_transcription/cache/huggingface/hub/models--CohereLabs--cohere-transcribe-03-2026/snapshots/b1eacc2686a3d08ceaae5f24a88b1d519620bc09 /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/fold_$G --group $G --lr 1e-5 --seed 1 --patience 4 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/train_fold_$G.log 2>&1
for tgt in $OTHER T; do /kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_decode.py /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/fold_$G/best /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/input_enspa/miami_kfold/miami_$tgt /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/kfold/hyps/cohere_train$G_on$tgt.csv es 32 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/dec_fold_${G}_$tgt.log 2>&1; done
/kaggle/working/omni_rt/venv/bin/python -u /kaggle/working/omni_rt/cohere_decode.py /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/fold_$G/best /kaggle/working/omni_rt/dev /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/kfold/hyps/cohere_train$G_ondev.csv es 16 > /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/dec_fold_${G}_dev.log 2>&1
echo FOLD_${G}_DONE >> /home/jovyan/work/2026_08_Mozilla_Lost_In_Transcription/lost-in-transcription-spanish-english-track/cohere/train_fold_$G.log
